Reproduce code
```ts
import { test, expect, type CDPSession, type Page } from '@playwright/test';

test('raw CDP reports Promise was collected for an unretained cross-frame promise', async ({ page, browserName }) => {
  test.skip(browserName !== 'chromium', 'Chromium/V8-specific CDP behavior');

  const client = await page.context().newCDPSession(page);
  await installCrossFramePromiseFixture(page);

  const error = await reproducePromiseCollection(page, client, 'cdp');

  console.log(`Reproduced raw CDP error: ${error.message}`);
  expect(error.message).toContain('Promise was collected');
});

test('reproduces misleading page.evaluate error for a collected cross-frame promise', async ({ page, browserName }) => {
  test.skip(browserName !== 'chromium', 'Chromium/V8-specific CDP behavior');

  const client = await page.context().newCDPSession(page);
  await installCrossFramePromiseFixture(page);

  const error = await reproducePromiseCollection(page, client, 'playwright');

  console.log(`Reproduced Playwright error: ${error.message}`);
  expect(error.message).toContain('Execution context was destroyed, most likely because of a navigation.');
  expect(error.message).not.toContain('Promise was collected');
});

test('retaining and awaiting the cross-frame promise avoids collection', async ({ page, browserName }) => {
  test.skip(browserName !== 'chromium', 'Chromium/V8-specific CDP behavior');

  const client = await page.context().newCDPSession(page);
  await installCrossFramePromiseFixture(page);

  const resultPromise = page.evaluate(async () => {
    return window['__SomeE2EApi__'].waitForChangesAppliedAsync2();
  });

  await forceGarbageCollection(client);

  await expect(resultPromise).resolves.toBe('resolved from iframe');
});

async function installCrossFramePromiseFixture(page: Page) {
  await page.setContent(`
    <!doctype html>
    <html>
      <body>
        <iframe id="child" srcdoc="
          <!doctype html>
          <script>
            window.createUnretainedNeverSettlingPromise = () => new Promise(() => {});
            // window.createUnretainedNeverSettlingPromise = () => Promise.resolve()
            window.createUnretainedResolvingPromise = () => {
              const promise = new Promise(resolve => setTimeout(() => resolve('resolved from iframe'), 1000));
              return promise;
            };
          </script>
        "></iframe>
        <script>
          window.__SomeE2EApi__ = {
            waitForChangesAppliedAsync() {
              const child = document.querySelector('#child').contentWindow;
              return child.createUnretainedNeverSettlingPromise();
            },
            async waitForChangesAppliedAsync2() {
              const child = document.querySelector('#child').contentWindow;
              return await child.createUnretainedResolvingPromise();
            }
          };
        </script>
      </body>
    </html>
  `);

  await page.waitForFunction(() => {
    const child = document.querySelector('iframe')?.contentWindow;
    return !!window['__SomeE2EApi__'] && !!child?.['createUnretainedNeverSettlingPromise'];
  });
}

async function reproducePromiseCollection(page: Page, client: CDPSession, mode: 'cdp' | 'playwright'): Promise<Error> {
  let lastResult: unknown;
  for (let attempt = 0; attempt < 30; ++attempt) { // 1 is probably enough
    const resultPromise = mode === 'cdp' ? client.send('Runtime.evaluate', {
      expression: 'window.__SomeE2EApi__.waitForChangesAppliedAsync()',
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    }).catch(e => e) : page.evaluate(() => window['__SomeE2EApi__'].waitForChangesAppliedAsync()).catch(e => e);

    await forceGarbageCollection(client);

    lastResult = await Promise.race([
      resultPromise,
      new Promise(resolve => setTimeout(() => resolve('timed out waiting for evaluation result'), 5000)),
    ]);

    if (lastResult instanceof Error)
      return lastResult;
  }

  throw new Error(`Did not reproduce promise collection. Last result: ${String(lastResult)}`);
}

async function forceGarbageCollection(client: CDPSession) {
  for (let i = 0; i < 20; ++i)
    await client.send('HeapProfiler.collectGarbage');
}
```

