import { test, expect, type CDPSession, type Page } from '@playwright/test';

test('promise collected', async ({ page }) => {
  const resultPromise = page.evaluate(() => {
    window['createPromise'] = () => new Promise(() => {});
    const promise = window['createPromise']();
    window['promise'] = promise;
    return promise.finally(() => {
      window['promise'] = null;
    });
  }).catch(e => e);
  for (let i = 0; i < 20; i++)
    await page.requestGC();
  console.log((await resultPromise).message);
});
```
